const items = $input.all();

return items.map((item) => {
  const lead = item.json.body ?? item.json;

  const errors = [];

  const email = String(lead.email ?? "")
    .trim()
    .toLowerCase();

  const firstName = String(lead.first_name ?? "").trim();
  const lastName = String(lead.last_name ?? "").trim();
  const company = String(lead.company ?? "").trim();
  const message = String(lead.message ?? "").trim();

  const emailPattern = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

  if (!emailPattern.test(email)) {
    errors.push("Invalid email address");
  }

  if (!firstName) {
    errors.push("First name is required");
  }

  if (!company) {
    errors.push("Company name is required");
  }

  if (!message) {
    errors.push("Requirement description is required");
  }

  const budgetProvided =
    lead.budget !== undefined &&
    lead.budget !== null &&
    lead.budget !== "";

  const budget = budgetProvided
    ? Number(lead.budget)
    : null;

  if (
    budgetProvided &&
    (!Number.isFinite(budget) || budget < 0)
  ) {
    errors.push("Budget must be a non-negative number");
  }

  const valid = errors.length === 0;

  return {
    json: {
      ...lead,
      first_name: firstName,
      last_name: lastName,
      email,
      company,
      message,
      budget,
      validation: {
        valid,
        errors
      },
      processed_at: new Date().toISOString()
    }
  };
});

const response = $input.first().json;

const lead = $('Validate Lead Data').item.json;

const company = response.data ?? {};

const enrichment = {
  source: "hunter",
  found: Boolean(company.id || company.domain),
  company_name: company.name ?? null,
  company_domain: company.domain ?? lead.company_domain ?? null,
  industry: company.category?.industry ??
            company.category?.sector ??
            null,
