  }
}];

const response = $input.first().json;

const content = response.choices?.[0]?.message?.content;

if (!content) {
  throw new Error("Groq returned an empty response");
}

let qualification;

try {
  qualification = JSON.parse(content);
} catch {
  throw new Error("Groq returned invalid JSON");
}

const allowed = ["HIGH", "MEDIUM", "LOW", "UNKNOWN"];

for (const field of [
  "service_match",
  "authority",
  "urgency",
  "requirement_clarity"
]) {
  if (!allowed.includes(qualification[field])) {
    throw new Error(`Invalid or missing classification: ${field}`);
  }
}

const originalLead = $('Validate Lead Data').first().json;

return [{
  json: {
    ...originalLead,
    ai_qualification: qualification
  }
}];

const lead = $input.first().json;
const ai = lead.ai_qualification;

if (!ai) {
  throw new Error("AI qualification data is missing");
}

let score = 0;
const breakdown = {};

// 1. Budget (maximum 25 points)
const budget = Number(lead.budget);

if (lead.budget != null && Number.isFinite(budget)) {
  if (budget >= 10000) {
    score += 25;
    breakdown.budget = 25;
  } else if (budget >= 5000) {
    score += 15;
    breakdown.budget = 15;
  } else if (budget >= 1000) {
    score += 5;
    breakdown.budget = 5;
  } else {
    breakdown.budget = 0;
  }
} else {
  breakdown.budget = 0;
}

// 2. Service fit (maximum 25 points)
const serviceScores = {
  HIGH: 25,
  MEDIUM: 15,
  LOW: 0,
  UNKNOWN: 0
};

breakdown.service_fit =
  serviceScores[ai.service_match] ?? 0;

score += breakdown.service_fit;

// 3. Authority (maximum 20 points)
const authorityScores = {
  HIGH: 20,
  MEDIUM: 10,
  LOW: 0,
  UNKNOWN: 0
};

breakdown.authority =
  authorityScores[ai.authority] ?? 0;

score += breakdown.authority;

// 4. Timeline (maximum 15 points)
const days = Number(lead.timeline_days);

if (lead.timeline_days != null &&
    Number.isFinite(days) && days > 0) {
  if (days <= 30) {
    breakdown.timeline = 15;
  } else if (days <= 90) {
    breakdown.timeline = 10;
  } else if (days <= 180) {
    breakdown.timeline = 5;
  } else {
    breakdown.timeline = 0;
  }
} else {
  breakdown.timeline = 0;
}

score += breakdown.timeline;

// 5. Company size (maximum 15 points)
const size = Number(lead.company_size);

if (lead.company_size != null &&
    Number.isFinite(size) && size > 0) {
  if (size >= 20 && size <= 500) {
    breakdown.company_size = 15;
  } else if (size < 20) {
    breakdown.company_size = 10;
  } else {
    breakdown.company_size = 5;
  }
} else {
  breakdown.company_size = 0;
}

score += breakdown.company_size;

// 6. Classification
let category;

if (
  ai.service_match === "LOW" ||
  ai.service_match === "UNKNOWN"
) {
  category = "REVIEW";
} else if (score >= 75) {
  category = "HOT";
} else if (score >= 45) {
  category = "WARM";
} else {
  category = "COLD";
}

return [{
  json: {
    ...lead,
    lead_score: score,
    lead_category: category,
    score_breakdown: breakdown,
    qualification_reason: ai.reason ?? "",
    scored_at: new Date().toISOString()
  }
}];

