const response = $input.first().json;

const content = response.choices?.[0]?.message?.content;

if (!content) {
  throw new Error("Groq returned an empty response");
}

let email;

try {
  email = JSON.parse(content);
} catch (error) {
  throw new Error("Groq returned invalid JSON");
}

if (
  typeof email.subject !== "string" ||
  typeof email.body !== "string" ||
  !email.subject.trim() ||
  !email.body.trim()
) {
  throw new Error("Invalid generated email");
}

if (email.subject.length > 150) {
  throw new Error("Email subject is too long");
}

if (email.body.trim().split(/\s+/).length > 130) {
  throw new Error("Generated email exceeds 130 words");
}

const lead = $('Calculate Lead Score').first().json;

return [{
  json: {
    ...lead,
    email_draft: {
      subject: email.subject.trim(),
      body: email.body.trim()
    },
    email_status: "PENDING_APPROVAL"
  }
}];

